#pragma once
static void checkTerminalDrag(App& app,const std::string& dir){
    auto require=[](bool ok,const std::string& why){if(!ok)throw std::runtime_error("terminal drag: "+why);};auto& s=app.s;
    std::set<const compounddata::Entry*> checked;std::ofstream inventory(dir+"/terminal-drag-library.tsv");int count=0;
    for(const auto& row:studio_terminal_drag::entries()){
        const auto& end=row.second;auto compound=compounddata::find(end.label);if(!compound||!checked.insert(compound).second)continue;
        s.cancel();s.doc=Document();s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());s.activateCommand("chooseSelectionTool_Marquee");ObjectId host;s.doc.addAtom(Vec2(100,100),6,&host);require(nicknames::apply(s.doc,host,end.label).ok(),"create compact "+end.label);s.refresh();s.fit();auto before=s.doc.digest();auto formula=studio::analyze(s.doc,s.all());
        const auto visual=arrows::mechanismVisualBoxes(s.doc).at(host);require(visual.hasTerminal,"terminal glyph capture "+end.label);auto press=(visual.terminal.min+visual.terminal.max)*.5;require(app.beginElectronMarkerDrag(s.view().toDevice(press)),"grab "+end.label);auto drop=s.view().toDevice(press+Vec2(50,25));app.updateElectronMarkerDrag(drop,false);require(app.attachedProtonPreview&&s.doc.digest()==before,"reversible terminal preview "+end.label);app.updateElectronMarkerDrag(drop,true);
        require(s.selected.size()==1&&s.doc.atoms().alive(s.selected.front().id)->element==end.element,"one explicit halogen "+end.label);auto after=studio::analyze(s.doc,s.all());require(formula.valid&&after.valid&&formula.plain==after.plain&&std::abs(formula.averageMass-after.averageMass)<.001,"composition preserved "+end.label+": "+formula.plain+" -> "+after.plain);
        if(end.label=="CH3I"||end.label=="MeI"){require(s.save(dir+"/pulled-methyl-iodide.cdxml",true).ok(),"save methyl iodide");s.selected={ObjectRef(ObjectKind::Atom,host)};app.expandPending=false;app.expandGroups();require(s.doc.atoms().alive(host)->semantics.implicitHydrogens==3&&s.doc.atoms().alive(host)->semantics.showLabel,"first methyl stage displays CH3");auto stage=s.doc.digest();app.expandGroups();require(s.doc.stats().aliveAtoms==5&&s.doc.incidentBonds(host).size()==4&&s.doc.atoms().alive(host)->semantics.implicitHydrogens==0,"second methyl stage exposes exactly three hydrogens");auto explicitFormula=studio::analyze(s.doc,s.all());require(explicitFormula.plain==formula.plain,"methyl stages preserve formula");require(s.undo().ok()&&s.doc.digest()==stage,"explicit methyl hydrogens undo separately");}
        else require(s.undo().ok()&&s.doc.digest()==before,"terminal extraction undo "+end.label);
        inventory<<compound->title<<'\t'<<end.label<<'\t'<<end.token<<'\t'<<end.base<<'\n';++count;
    }
    require(count>=10,"library-wide terminal halogen coverage");
    s.cancel();s.doc=Document();s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());ObjectId caption;s.doc.addText(Vec2(100,100),10,"CH3I",&caption);s.refresh();s.fit();auto beforeCaption=s.doc.digest();auto end=studio_terminal_drag::find("CH3I");require(end,"CH3I is indexed");
    text::LayoutOptions options;options.defaultSize=10;options.defaultFont=s.doc.defaultFont();text::RichLayout layout;require(text::layoutRichText(s.doc.runs(caption),Vec2(),options,&s.glyphs,&layout).ok(),"caption layout");auto glyph=layout.glyphs.back();Box ink;bool any=false;for(auto contour:glyph.contours)for(auto p:contour){p=p+Vec2(100,100-layout.metrics.firstBaseline);if(any)ink.add(p);else{ink=Box(p,p);any=true;}}auto press=(ink.min+ink.max)*.5;require(app.beginElectronMarkerDrag(s.view().toDevice(press)),"plain CH3I caption I capture");app.updateElectronMarkerDrag(s.view().toDevice(press+Vec2(50,0)),true);require(s.doc.stats().aliveAtoms==2&&s.doc.stats().aliveTexts==0,"caption becomes two bonded atoms");require(s.undo().ok()&&s.doc.digest()==beforeCaption,"caption terminal undo");
    s.doc=Document();s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());ObjectId carbon,iodine,bond;s.doc.addAtom(Vec2(50,50),6,&carbon);s.doc.addAtom(Vec2(80,50),53,&iodine);s.doc.addBond(carbon,iodine,&bond);s.selected={ObjectRef(ObjectKind::Atom,carbon)};s.refresh();auto skeleton=s.doc.digest();app.expandPending=false;app.expandGroups();auto labeled=s.doc.digest();require(s.doc.atoms().alive(carbon)->semantics.showLabel&&s.doc.atoms().alive(carbon)->semantics.implicitHydrogens==3,"bare methyl first stage");app.expandGroups();require(s.doc.stats().aliveAtoms==5&&s.doc.bondBetween(carbon,iodine)==bond,"bare methyl hydrogens retain original C--I bond");require(s.undo().ok()&&s.doc.digest()==labeled&&s.undo().ok()&&s.doc.digest()==skeleton,"both methyl stages undo independently");
    s.doc=Document();s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());ObjectId radical;s.doc.addAtom(Vec2(100,100),50,&radical);require(nicknames::apply(s.doc,radical,"Bu3Sn·").ok(),"tin radical label");s.refresh();integration::RingGeometry rings(s.doc);auto labels=integration::molecular::labels(s.doc,s.glyphs,rings);auto placed=labels.at(radical).layout;auto dots=arrows::mechanismRadicalPositions(s.doc,*s.doc.atoms().alive(radical),10,&placed);double low=1e100,high=-1e100;for(const auto& g:placed.glyphs)if(g.size>=9)for(auto contour:g.contours)for(auto p:contour){low=std::min(low,p.y+placed.anchor.y);high=std::max(high,p.y+placed.anchor.y);}require(dots.size()==1&&std::abs(dots[0].y-(low+high)*.5)<1e-7&&dots[0].x>placed.metrics.inkBox.max.x,"radical defaults to right middle");s.selected.clear();s.fit();app.invalidate();app.screenshot(dir+"/radical-right-middle.png");require(s.save(dir+"/radical-right-middle.cdxml",true).ok(),"save right-middle radical");
    std::ofstream(dir+"/terminal-drag-checks.json")<<"{\"reviewed_compounds\":"<<count<<",\"composition_preserved\":true,\"preview_undo\":true,\"methyl_two_stages\":true}";
}
